const inp = $('Entrada').first().json;
const cfg = $input.all().map(i => i.json).filter(r => r.client_id);
const bad = (error) => [{ json: { valid: false, action: 'invalido', error: error } }];
if (cfg.length !== 1) return bad('No pude identificar a Alianz en la suite (clients). Avisá que hubo un problema y derivá al asesor.');
const clean = v => (v === undefined || v === null) ? '' : String(v).trim();
const digits = clean(inp.telefono).replace(/[^0-9]/g, '');
let hora = clean(inp.hora).replace('.', ':').replace(/[^0-9:]/g, '');
if (/^[0-9]{1,2}$/.test(hora)) hora = hora + ':00';
if (/^[0-9]:[0-9]{2}$/.test(hora)) hora = '0' + hora;
const d = {
  valid: true, action: clean(inp.action), client_id: Number(cfg[0].client_id),
  telefono: digits, tel10: digits.slice(-10) || '#sin-telefono#',
  patente: clean(inp.patente).toUpperCase().replace(/[^A-Z0-9]/g, ''),
  nombre: clean(inp.nombre), apellido: clean(inp.apellido), email: clean(inp.email).toLowerCase(),
  modelo: clean(inp.modelo), sucursal: clean(inp.sucursal).toUpperCase(),
  fecha: clean(inp.fecha).slice(0, 10), hora: hora,
  customer_id: parseInt(clean(inp.customer_id), 10) || 0, vehicle_id: parseInt(clean(inp.vehicle_id), 10) || 0,
  appointment_id: parseInt(clean(inp.appointment_id), 10) || 0,
  tipo_lavado: clean(inp.tipo_lavado), motivo: clean(inp.motivo), notas: clean(inp.notas),
};
d.patq = d.patente || '#sin-patente#';
const okFecha = /^20[0-9]{2}-[01][0-9]-[0-3][0-9]$/.test(d.fecha);
const okHora = /^[0-2][0-9]:[0-5][0-9]$/.test(d.hora);
const a = d.action;
if (a === 'buscar_cliente' || a === 'mis_turnos') { if (!digits && !d.patente) return bad('Falta teléfono o patente.'); }
else if (a === 'registrar_cliente') { if (!digits) return bad('Falta el teléfono.'); if (!d.nombre) return bad('Falta el nombre.'); if (d.patente.length < 6) return bad('La patente no es válida: pedila de nuevo.'); }
else if (a === 'turnos_disponibles') { if (!d.sucursal) return bad('Falta la sucursal.'); if (d.fecha && !okFecha) return bad('La fecha debe ser AAAA-MM-DD.'); }
else if (a === 'agendar') { if (!d.sucursal) return bad('Falta la sucursal.'); if (!okFecha || !okHora) return bad('Fecha (AAAA-MM-DD) y hora (HH:MM) obligatorias, tal cual las devolvió turnos_disponibles.'); if (!d.customer_id || !d.vehicle_id) return bad('Faltan customer_id y vehicle_id: ejecutá buscar_cliente o registrar_cliente primero.'); }
else if (a === 'modificar') { if (!d.appointment_id) return bad('Falta appointment_id (sale de mis_turnos).'); if (!okFecha || !okHora) return bad('Fecha (AAAA-MM-DD) y hora (HH:MM) obligatorias.'); if (!digits) return bad('Falta el teléfono.'); }
else if (a === 'cancelar') { if (!d.appointment_id) return bad('Falta appointment_id (sale de mis_turnos).'); if (!digits) return bad('Falta el teléfono.'); }
else return bad('Acción inválida: ' + a);
return [{ json: d }];

const p = $('Validar').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.customer_id);
if (!rows.length) return [{ json: { success: true, encontrado: false, message: p.action === 'registrar_cliente' ? 'No se pudo registrar al cliente. Avisá que hubo un problema y derivá al asesor.' : 'No hay un cliente registrado con ese teléfono o patente. Pedile los datos y usá registrar_cliente.' } }];
const byId = {};
for (const r of rows) {
  if (!byId[r.customer_id]) byId[r.customer_id] = { customer_id: r.customer_id, nombre: r.first_name || '', apellido: r.last_name || '', email: r.email || '', telefono: r.mobile || r.phone || '', vehiculos: [] };
  if (r.vehicle_id) byId[r.customer_id].vehiculos.push({ vehicle_id: r.vehicle_id, patente: r.license_plate, modelo: r.modelo || '', version: r.version || '' });
}
const clientes = Object.values(byId);
return [{ json: { success: true, encontrado: true, registrado: p.action === 'registrar_cliente', clientes: clientes, message: 'Usá customer_id y vehicle_id de acá para agendar. Si un vehículo tiene modelo vacío, mostralo solo con la patente y preguntá el modelo para el resumen (no hace falta registrarlo de nuevo). Si el vehículo no está en la lista, pedí patente y modelo y usá registrar_cliente.' } }];

const rows = $input.all().map(i => i.json).filter(r => r.appointment_id);
const turnos = rows.map(r => ({ appointment_id: r.appointment_id, fecha: r.fecha, hora: r.hora, hora_fin: r.hora_fin, sucursal: r.branch_name, patente: r.patente, detalle: r.detalle }));
return [{ json: { success: true, turnos: turnos, message: turnos.length ? 'Estos son los turnos de lavado vigentes del cliente.' : 'El cliente no tiene turnos de lavado vigentes.' } }];

const DAYS = ['DO','LU','MA','MI','JU','VI','SA'];
const DIAS = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
function dow(ds) { return new Date(ds + 'T12:00:00Z').getUTCDay(); }
function isServiceDay(b, ds) { return String(b.service_days || 'LU-MA-MI-JU-VI-SA').toUpperCase().split(/[-, ]+/).includes(DAYS[dow(ds)]); }
function hoursFor(b, ds) { const we = dow(ds) === 0 || dow(ds) === 6; return { open: (we && b.open_time_weekend) ? b.open_time_weekend : (b.open_time || '08:00'), close: (we && b.close_time_weekend) ? b.close_time_weekend : (b.close_time || '18:00') }; }
function utc(ds, hm) { const parts = String(hm).split(':').map(Number); const d = new Date(ds + 'T00:00:00Z'); d.setUTCHours(parts[0] + 3, parts[1] || 0, 0, 0); return d; }
function hhmm(d) { return String(d.getUTCHours() - 3).padStart(2, '0') + ':' + String(d.getUTCMinutes()).padStart(2, '0'); }
function blocksFor(b, ds) { const out = []; const add = (t, m) => { if (!t || !m || Number(m) <= 0) return; const s = utc(ds, t); out.push({ s: s, e: new Date(s.getTime() + Number(m) * 60000) }); }; add(b.lunch_start_time, b.lunch_duration); add(b.break1_time, b.break1_duration); add(b.break2_time, b.break2_duration); add(b.break3_time, b.break3_duration); return out; }
function todayAR() { return new Date(Date.now() - 3 * 3600000).toISOString().slice(0, 10); }
function minAllowed(b) { return new Date(Date.now() + (Number(b.confirmation_hours) || 0) * 3600000); }
function checkSlot(b, ds, hora, dur) { if (ds <= todayAR()) return 'muy_pronto'; if (!isServiceDay(b, ds)) return 'not_service_day'; const h = hoursFor(b, ds); const s = utc(ds, hora); const e = new Date(s.getTime() + dur * 60000); if (s < utc(ds, h.open) || e > utc(ds, h.close)) return 'fuera_horario'; if (blocksFor(b, ds).some(x => s < x.e && e > x.s)) return 'fuera_horario'; if (s < minAllowed(b)) return 'muy_pronto'; return ''; }
function busyOf(it) { const s = new Date(it.start && it.start.dateTime ? it.start.dateTime : it.start); const e = new Date(it.end && it.end.dateTime ? it.end.dateTime : it.end); return (isNaN(s) || isNaN(e)) ? null : { s: s, e: e }; }
