const t = $input.first().json;
if (!t.appointment_id) return [{ json: { ok: false, reason: 'no_encontrado' } }];
const dur = Number(t.estimated_duration) || 30;
const why = checkSlot(t, p.fecha, p.hora, dur);
if (why) return [{ json: { ok: false, reason: why } }];
const s = utc(p.fecha, p.hora), e = new Date(s.getTime() + dur * 60000);
return [{ json: { ok: true, appointment_id: t.appointment_id, calendar_id: String(t.calendar_id || '').trim(), event_id: t.google_event_id, start_iso: s.toISOString(), end_iso: e.toISOString(), hora_fin: hhmm(e), branch_name: t.branch_name, old: t.fecha + ' ' + t.hora } }];

const c = $('Preparar cambio').first().json;
const evs = $input.all().map(i => i.json);
if (evs.some(e => e.error)) return [{ json: { ok: false, reason: 'error_agenda' } }];
const otros = evs.filter(e => e.id && e.id !== c.event_id && e.status !== 'cancelled' && e.transparency !== 'transparent');
return [{ json: Object.assign({}, c, { ok: otros.length === 0, reason: otros.length ? 'ocupado' : '' }) }];

