const c = $('Revisar conflicto').first().json;
return [{ json: { success: true, appointment_id: c.appointment_id, fecha: p.fecha, hora: p.hora, hora_fin: c.hora_fin, sucursal: c.branch_name, message: 'Turno de lavado modificado. Confirmale al cliente la nueva fecha y hora.' } }];

